--
-- Name: centenas(numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.centenas(prdigito numeric, prdecena numeric, prunidad numeric) RETURNS character
    LANGUAGE plpgsql
    AS $$
 
DECLARE strVlrLetras character(20);
BEGIN
    IF prDigito = 1 THEN 
       IF prDecena > 0 OR prUnidad > 0 THEN
           strVlrLetras = 'CIENTO ';
       ELSE
           strVlrLetras = 'CIEN '; 
       END IF;
    END IF;
    IF prDigito = 2 THEN 
        strVlrLetras = 'DOSCIENTOS '; 
    END IF;
    IF prDigito = 3 THEN 
        strVlrLetras = 'TRESCIENTOS '; 
    END IF;
    IF prDigito = 4 THEN 
        strVlrLetras = 'CUATROCIENTOS '; 
    END IF;
    IF prDigito = 5 THEN 
        strVlrLetras = 'QUINIENTOS '; 
    END IF;
    IF prDigito = 6 THEN 
        strVlrLetras = 'SEISCIENTOS '; 
    END IF;
    IF prDigito = 7 THEN 
        strVlrLetras = 'SETECIENTOS '; 
    END IF;
    IF prDigito = 8 THEN 
        strVlrLetras = 'OCHOCIENTOS '; 
    END IF;
    IF prDigito = 9 THEN 
        strVlrLetras = 'NOVECIENTOS '; 
    END IF;
    RETURN strVlrLetras;
END 
$$;


