--
-- Name: creaestanciaautomatica(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.creaestanciaautomatica() RETURNS character varying
    LANGUAGE plpgsql
    AS $$DECLARE  estancias character(50000);
          tablaGeneral  RECORD;
  	 	tablaEstancia  RECORD;
         tabla  RECORD;

BEGIN
	FOR tablaGeneral 
	IN
	SELECT servSedes.id servSedesId, serv.id servId,dep.id depId,* 
	FROM sitios_serviciossedes servSedes
	INNER JOIN clinico_servicios serv ON (serv.id = servSedes.servicios_id)
	INNER JOIN sitios_dependencias dep ON (dep."serviciosSede_id" = servSedes.id)
	WHERE servSedes."sedesClinica_id" = 1 AND serv.nombre in ('HOSPITALIZACION', 'URGENCIAS')
	ORDER BY dep.id
	LOOP
		FOR tablaEstancia
		IN
		SELECT 	(SELECT  (coalesce(max(liqDet.consecutivo), 1) +1) AS MaxX	FROM facturacion_liquidaciondetalle liqdet WHERE liqDet.liquidacion_id = l1.id) consecutivo, now() fecha,1 noSe,tarEstancias.valor valorUnitario,tarEstancias.valor valor,now() fechaRegistro,'' nada, now() otraFecha,'A' estado,tarEstancias.cups_id cupsId,l1.id liqId,'SISTEMA' tipoTx,'N' anulado,tarEstancias.homologado	hmologacion FROM facturacion_liquidacion l1 INNER JOIN admisiones_ingresos ing ON  (ing."tipoDoc_id" = l1."tipoDoc_id" AND ing.documento_id = l1.documento_id and ing.consec = l1."consecAdmision") LEFT JOIN clinico_especialidadesmedicos espMed on (espMed.id = ing."especialidadesMedicosActual_id") INNER JOIN sitios_dependencias dep on (dep.id = ing."dependenciasActual_id") INNER JOIN sitios_serviciossedes servSedes ON (servSedes.id =dep."serviciosSedes_id" ) left JOIN facturacion_conveniospacienteingresos convIng on (convIng."tipoDoc_id" = ing."tipoDoc_id" AND convIng.documento_id = ing.documento_id and convIng."consecAdmision"=ing.consec) left JoIN contratacion_convenios conv ON (conv.id = convIng.convenio_id) left JOIN tarifarios_tarifariosdescripcion descripcion ON (descripcion.id =conv."tarifariosDescripcionProc_id" ) left JOIN tarifarios_estancias tarEstancias ON (tarEstancias."tiposTarifa_id" = descripcion."tiposTarifa_id" AND tarEstancias.cups_id = dep.cups_id  and tarEstancias."especialidadesEnEstancias_id" = espMed.especialidades_id) INNER JOIN clinico_nivelesclinica nivel ON (nivel.id = tarEstancias."nivelesClinica_id" ) left join tarifarios_tipostarifa  tiptarifa 	on (tiptarifa.id=tarEstancias."tiposTarifa_id") INNER JOIN facturacion_empresas emp on (emp.nombre ='CLINICA MEDICAL S.A.S' AND emp."nivelesClinica_id" = nivel.id) WHERE servSedes.id = tablaGeneral.servSedesId AND dep.id = tablaGeneral.depId
		LOOP 	
				observaciones, "fechaRegistro", "estadoRegistro", examen_id, liquidacion_id 
				,"tipoRegistro",anulado, "codigoHomologado") 	 values (tablaEstancia.MaxX, tablaEstancia.consecutivo, tablaEstancia.fecha, tablaEstancia.noSe,
			tablaEstancia.valorUnitario, tablaEstancia.valor,tablaEstancia.fechaRegistro, tablaEstancia.nada,
			    tablaEstancia.otraFecha, tablaEstancia.estado, tablaEstancia.cupsId,tablaEstancia.liqId,
			tablaEstancia.tipoTx, 	tablaEstancia.anulado,	tablaEstancia.hmologacion);
		
			raise notice 'Ya insert:' ;

			raise notice 'Voy a guardar encabezados : %s' , tabla.id;
			Update facturacion_liquidacion SET  "totalProcedimientos" = "totalProcedimientos" + tablaEstancia.valor        where id = tablaEstancia.liqId;
			raise notice 'ya guarde1: %s' , tabla.id;
			Update facturacion_liquidacion SET  "totalLiquidacion" = "totalSuministros" + "totalProcedimientos"    where id = tablaEstancia.liqId;
			raise notice 'ya guarde2: : %s' , tabla.id;
			Update facturacion_liquidacion SET  "valorApagar" = "totalLiquidacion" - "totalRecibido"    where id = tablaEstancia.liqId;
			raise notice 'En teoria ya guardes : %s' , tabla.valor;
		
		END LOOP;

	END LOOP;

RETURN 'OK'; 
END $$;


ALTER FUNCTION public.creaestanciaautomatica() OWNER TO postgres;

--
-- Name: creaestanciaautomatica(numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.creaestanciaautomatica(sede numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE  estancias character(50000);
          tablaGeneral  RECORD;
  	 	tablaEstancia  RECORD;
		tablaTotales  RECORD;
         tabla  RECORD;
		totalProc numeric;

BEGIN
	raise notice 'Entre' ;

	FOR tablaGeneral 
	IN
	SELECT servSedes.id servSedesId, serv.id servId,dep.id depId,* 
	FROM sitios_serviciossedes servSedes
	INNER JOIN clinico_servicios serv ON (serv.id = servSedes.servicios_id)
	INNER JOIN sitios_dependencias dep ON (dep."serviciosSedes_id" = servSedes.id)
	WHERE servSedes."sedesClinica_id" = sede AND serv.nombre in ('HOSPITALIZACION', 'URGENCIAS')
	ORDER BY dep.id
	LOOP
		raise notice 'A recorrer dependencias' ;
		FOR tablaEstancia
		IN
		SELECT 	(SELECT  (coalesce(max(liqDet.consecutivo), 1) +1) AS MaxX	FROM facturacion_liquidaciondetalle liqdet WHERE liqDet.liquidacion_id = l1.id) consecutivo, now() fecha,1 noSe,tarEstancias.valor valorUnitario,tarEstancias.valor valor,now() fechaRegistro,'' nada, now() otraFecha,'A' estado,tarEstancias.cups_id cupsId,l1.id liqId,'SISTEMA' tipoTx,'N' anulado,tarEstancias.homologado	hmologacion FROM facturacion_liquidacion l1 INNER JOIN admisiones_ingresos ing ON  (ing."tipoDoc_id" = l1."tipoDoc_id" AND ing.documento_id = l1.documento_id and ing.consec = l1."consecAdmision") LEFT JOIN clinico_especialidadesmedicos espMed on (espMed.id = ing."especialidadesMedicosActual_id") INNER JOIN sitios_dependencias dep on (dep.id = ing."dependenciasActual_id") INNER JOIN sitios_serviciossedes servSedes ON (servSedes.id =dep."serviciosSedes_id" ) left JOIN facturacion_conveniospacienteingresos convIng on (convIng."tipoDoc_id" = ing."tipoDoc_id" AND convIng.documento_id = ing.documento_id and convIng."consecAdmision"=ing.consec) left JoIN contratacion_convenios conv ON (conv.id = convIng.convenio_id) left JOIN tarifarios_tarifariosdescripcion descripcion ON (descripcion.id =conv."tarifariosDescripcionProc_id" ) left JOIN tarifarios_estancias tarEstancias ON (tarEstancias."tiposTarifa_id" = descripcion."tiposTarifa_id" AND tarEstancias.cups_id = dep.cups_id  and tarEstancias."especialidadesEnEstancias_id" = espMed.especialidades_id) INNER JOIN clinico_nivelesclinica nivel ON (nivel.id = tarEstancias."nivelesClinica_id" ) left join tarifarios_tipostarifa  tiptarifa 	on (tiptarifa.id=tarEstancias."tiposTarifa_id") INNER JOIN facturacion_empresas emp on (emp.nombre ='CLINICA MEDICAL S.A.S' AND emp."nivelesClinica_id" = nivel.id) WHERE servSedes.id = tablaGeneral.servSedesId AND dep.id = tablaGeneral.depId
		LOOP 	
				raise notice 'VOy a INSERTAR' ;
				observaciones, "fechaRegistro", "estadoRegistro", examen_id, liquidacion_id 
				,"tipoRegistro",anulado, "codigoHomologado") 	 values (tablaEstancia.consecutivo, tablaEstancia.fecha, tablaEstancia.noSe,
			tablaEstancia.valorUnitario, tablaEstancia.valor,tablaEstancia.fechaRegistro, tablaEstancia.nada,
			    tablaEstancia.otraFecha, tablaEstancia.estado, tablaEstancia.cupsId,tablaEstancia.liqId,
			tablaEstancia.tipoTx, 	tablaEstancia.anulado,	tablaEstancia.hmologacion);
		
			raise notice 'Ya insert:' ;



		END LOOP;

	END LOOP;

	FOR tablaTotales
	IN
	SELECT servSedes.id servSedesId, serv.id servId,dep.id depId,fac.id facId,* 
	FROM sitios_serviciossedes servSedes
	INNER JOIN clinico_servicios serv ON (serv.id = servSedes.servicios_id)
	INNER JOIN sitios_dependencias dep ON (dep."serviciosSedes_id" = servSedes.id)
	INNER JOIN facturacion_liquidacion fac ON (fac."tipoDoc_id" = dep."tipoDoc_id" AND fac.documento_id = dep.documento_id AND fac."consecAdmision" = dep.consec)
	WHERE servSedes."sedesClinica_id" = sede AND serv.nombre in ('HOSPITALIZACION', 'URGENCIAS')
	ORDER BY dep.id
	LOOP
			totalProc:=0;
			raise notice 'Voy a guardar encabezados liquiacion  : %s' , tablaTotales.facId;

			select sum("valorTotal") 	
			into totalProc	
			FROM facturacion_liquidaciondetalle where liquidacion_id= 4 AND  anulado='N' AND examen_id is not null;

		raise notice 'TotaProc =   : %s' , totalProc;

			Update facturacion_liquidacion SET  "totalProcedimientos" = totalProc  where id = tablaTotales.facId;
			
			Update facturacion_liquidacion SET  "totalLiquidacion" = "totalSuministros" + "totalProcedimientos"    where id = tablaTotales.facId;
			
			Update facturacion_liquidacion SET  "valorApagar" = "totalLiquidacion" - "totalRecibido"    where id = tablaTotales.facId;
			
					
	END LOOP;


RETURN 'OK'; 
END 
$$;


ALTER FUNCTION public.creaestanciaautomatica(sede numeric) OWNER TO postgres;

--
-- Name: decenas(numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.decenas(prdigito numeric, prunidad numeric) RETURNS character
    LANGUAGE plpgsql
    AS $$
 
DECLARE strVlrLetras character(20);
BEGIN
    IF prDigito = 0 THEN strVlrLetras = Unidades(prUnidad); 
    END IF;
    IF prDigito = 1 THEN 
           IF prUnidad = 0 THEN strVlrLetras = 'DIEZ '; 
           END IF;  
           IF prUnidad = 1 THEN strVlrLetras = 'ONCE '; 
           END IF;  
           IF prUnidad = 2 THEN strVlrLetras = 'DOCE '; 
           END IF;  
           IF prUnidad = 3 THEN strVlrLetras = 'TRECE '; 
           END IF;  
           IF prUnidad = 4 THEN strVlrLetras = 'CATORCE '; 
           END IF;  
           IF prUnidad = 5 THEN strVlrLetras = 'QUINCE '; 
           END IF;  
           IF prUnidad > 5 THEN strVlrLetras = 'DIECI' || Unidades(prUnidad) ; 
           END IF;  
    END IF;
    IF prDigito = 2 THEN 
           IF prUnidad = 0 THEN strVlrLetras = 'VEINTE '; 
           ELSE 
               strVlrLetras = 'VEINTI' || Unidades(prUnidad) ; 
           END IF;
    END IF;
        IF prDigito = 2 THEN 
           IF prUnidad = 0 THEN strVlrLetras = 'VEINTE '; 
           ELSE 
               strVlrLetras = 'VEINTI' || Unidades(prUnidad) ; 
           END IF;
    END IF;
    IF prDigito = 3 THEN 
           strVlrLetras = 'TREINTA ' || CASE WHEN prUnidad > 0 THEN 'Y ' || Unidades(prUnidad) ELSE '' END ; 
    END IF;
    IF prDigito = 4 THEN 
           strVlrLetras = 'CUARENTA ' || CASE WHEN prUnidad > 0 THEN 'Y ' || Unidades(prUnidad) ELSE '' END ; 
    END IF;
    IF prDigito = 5 THEN 
           strVlrLetras = 'CINCUENTA ' || CASE WHEN prUnidad > 0 THEN 'Y ' || Unidades(prUnidad) ELSE '' END ; 
    END IF;
    IF prDigito = 6 THEN 
           strVlrLetras = 'SESENTA ' || CASE WHEN prUnidad > 0 THEN 'Y ' || Unidades(prUnidad) ELSE '' END ; 
    END IF;
    IF prDigito = 7 THEN 
           strVlrLetras = 'SETENTA ' || CASE WHEN prUnidad > 0 THEN 'Y ' || Unidades(prUnidad) ELSE '' END ; 
    END IF;
    IF prDigito = 8 THEN 
           strVlrLetras = 'OCHENTA ' || CASE WHEN prUnidad > 0 THEN 'Y ' || Unidades(prUnidad) ELSE '' END ; 
    END IF;
    IF prDigito = 9 THEN 
           strVlrLetras = 'NOVENTA ' || CASE WHEN prUnidad > 0 THEN 'Y ' || Unidades(prUnidad) ELSE '' END ; 
    END IF;

    RETURN strVlrLetras;
END 
$$;


ALTER FUNCTION public.decenas(prdigito numeric, prunidad numeric) OWNER TO postgres;

--
-- Name: facturajsondian_2(numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.facturajsondian_2(facturaid numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$

	DECLARE valorJson character(50000);
		valorEmisor  character(50000);
		valorReceptor character(50000);
		valorDetalle character(50000);
		valorDetalleSuministros character(50000);
		valorTotales character(50000);
		valorFormaPago character(50000);

		valorFinalJson character(50000);
	    valorTransaccionYusuarios character(50000);
		contador integer := 1;
        totalProcedimientos integer :=0;
		totalSuministros integer :=0;
		vamos integer :=0;
		hasta integer :=0;
		mide integer :=0;
		tipo character(7) :='FACTURA';
	


BEGIN

	
if (tipo = 'FACTURA') then 

	raise notice 'entre %s', facturaId;

-- Factura
	SELECT '[{"tipoDocumento": "01",' || '"NumFac":'|| '"' || CASE WHEN trim(cast(fac.factura as text)) is null THEN 'null' ELSE fac.factura  END  || '","correo":'||	'"'|| CASE WHEN trim(cast(emp.correo as text)) is null THEN null ELSE emp.correo  END   || '","ciudadCodigo":'||	'"'|| CASE WHEN trim(cast(ciu."ciudadCodigoDian" as text)) is null THEN null ELSE ciu."ciudadCodigoDian"  END  || '","ciudadNombre":'||	'"'|| CASE WHEN trim(cast(ciu.nombre as text)) is null THEN null ELSE ciu.nombre  END  || '","paisCodigo":'||	'"'|| CASE WHEN trim(cast(pais."paisCodigoDian" as text)) is null THEN null ELSE pais."paisCodigoDian"  END  || '","paisNombre":'||	'"'|| CASE WHEN trim(cast(pais.nombre as text)) is null THEN null ELSE pais.nombre  END  || '", "FecFac": ' ||  '"'|| CASE WHEN trim(cast(fac."fechaFactura" as text)) is null THEN null ELSE fac."fechaFactura"  END || '"' || ',"HoraFac" : '  ||'"' || CASE WHEN trim(cast( cast("fechaFactura" as time) as text)) is null THEN null ELSE  cast("fechaFactura" as time)  END ||'",'||  '"NitFac":' ||'"'|| CASE WHEN trim(cast(sed.nit as text)) is null THEN 'null' ELSE sed.nit  END ||'"'  ||',"DocAdq":"' ||  CASE WHEN trim(cast(emp.documento as text)) is null THEN 'null' ELSE emp.documento  END ||'"'||',"ValFac":"' || CASE WHEN trim(cast(fac."totalFactura" as text)) is null THEN 0 ELSE fac."totalFactura"  END	||'"'||',"ValIva":"' || 0.00	||'"'||',"ValOtroIm":"' || 0.00	||'"'||',"ValTotFac":"' ||CASE WHEN trim(cast(fac."valorApagar" as text)) is null THEN 0 ELSE fac."valorApagar"  END	||'"'||'},'
	INTO valorJson
	FROM facturacion_facturacion fac
	INNER JOIN sitios_sedesclinica sed ON (sed.id= fac."sedesClinica_id")
	INNER JOIN facturacion_empresas emp on (emp.id = sed.empresa_id)	
	INNER JOIN sitios_ciudades ciu ON (ciu.id=emp.ciudad_id)
	LEFT JOIN sitios_paises  pais ON (pais.id=emp.departamento_id)
	WHERE  fac.id= facturaId;

raise notice 'entre2 fACTURA: %s', facturaId;

	valorFinalJson :=  valorJson;

raise notice 'Va esto en el valorFinalJson: %s' , valorFinalJson;

-- Datos del Emisor

	SELECT '{"emisor":{"nit":'||'"'||emp.documento|| '", "dv":'||'"'|| substring(emp.documento,11,1) || '",' || '"nombreRazonSocial": ' ||'"' || emp.nombre || '",'||'"tipoPersona":"1",' || '"correo":'||	'"' || CASE WHEN trim(cast(emp.correo as text)) is null THEN null ELSE emp.correo  END   || '","ciudadCodigo":'||	'"'|| CASE WHEN trim(cast(ciu."ciudadCodigoDian" as text)) is null THEN null ELSE ciu."ciudadCodigoDian"  END  || '","ciudadNombre":'||	'"'|| CASE WHEN trim(cast(ciu.nombre as text)) is null THEN null ELSE ciu.nombre  END  || '","paisCodigo":'||	'"'|| CASE WHEN trim(cast(pais."paisCodigoDian" as text)) is null THEN null ELSE pais."paisCodigoDian"  END  || '","paisNombre":'||	'"'|| CASE WHEN trim(cast(pais.nombre as text)) is null THEN null ELSE pais.nombre  END  ||'","direccion":{"codigomunicipio":'|| '"' || mun."municipioCodigoDian" ||'","direccion":' ||'"' || emp.direccion || '",'||'"departamento":' || '"' ||dep."departamentoCodigoDian"  || '",'||'"pais":' || '"' ||pais."paisCodigoDian"  || '"}}},'
	INTO valorEmisor
	FROm facturacion_empresas emp
	LEFT JOIN sitios_departamentos dep ON (dep.id=emp.departamento_id)
	LEFT JOIN sitios_municipios mun ON (mun.id=emp.municipio_id)
	LEFT JOIN sitios_ciudades ciu ON (ciu.id=emp.ciudad_id)
	LEFT JOIN sitios_paises  pais ON (pais.id=emp.departamento_id)
	WHERE emp.nombre ='CLINICA MEDICAL S.A.S';

	valorFinalJson := valorFinalJson || ' ' || valorEmisor;
raise notice 'Va esto DATOS EMISOR en el valorFinalJson: %s' , valorFinalJson;

-- Datos del Receptor

	SELECT '{"receptor": {"nit": ' || '"' || emp.documento || '", "dv" : "0", "nombreRazonSocial": ' || '"' ||emp.nombre || '","tipoPersona": "2","tipoDocumentoIdentificacion": "' ||CASE WHEN trim(cast(emp.documento as text)) is null THEN null ELSE emp.documento END || '","ciudadCodigo":'||	'"'|| CASE WHEN trim(cast(ciu."ciudadCodigoDian" as text)) is null THEN null ELSE ciu."ciudadCodigoDian"  END   || '","ciudadNombre":'||	'"'|| CASE WHEN trim(cast(ciu.nombre as text)) is null THEN null ELSE ciu.nombre  END   || '","paisCodigo":'||	'"'|| CASE WHEN trim(cast(pais."paisCodigoDian" as text)) is null THEN null ELSE pais."paisCodigoDian"  END  || '","paisNombre":'||	'"'|| CASE WHEN trim(cast(pais.nombre as text)) is null THEN null ELSE pais.nombre  END   || '", "direccion" : {"codigomunicipio":' || '"' || mun."municipioCodigoDian" || '",'||'"direccion": ' || '"' || emp.direccion || '","departamento":'|| '"' || dep.nombre   || '","ciudadNombre":'||	'"'|| CASE WHEN trim(cast(ciu.nombre as text)) is null THEN null ELSE ciu.nombre  END  || '"'        ||'}}},'
	
	INTO valorReceptor
	from facturacion_facturacion fac
	left join contratacion_convenios conv ON (conv.id=fac.convenio_id)
	left join facturacion_empresas emp ON (emp.id = conv.empresa_id)
	--inner join usuarios_usuarios usu on (usu.id = fac.documento_id)
	left join  sitios_departamentos dep ON (dep.id = emp.departamento_id)
	left join sitios_municipios mun ON (mun.id=emp.municipio_id)
	left join sitios_ciudades ciu ON (ciu.id=emp.ciudad_id)
	LEFT JOIN sitios_paises  pais ON (pais.id=emp.departamento_id)
	where fac.id=facturaId;

raise notice 'valorReceptor: %s' , valorReceptor;
	valorFinalJson := valorFinalJson || ' ' || valorReceptor;
raise notice 'Va esto DATOS RECEPTOR en el valorFinalJson: %s' , valorFinalJson;


-- Detalle de ítems (Líneas)

totalProcedimientos  = (select count(*) from facturacion_facturacion fac inner join facturacion_facturaciondetalle det ON (det.facturacion_id = fac.id And det.anulado in ('N','R') and det."estadoRegistro" = 'A') inner join clinico_examenes exa ON  (exa.id =det.examen_id) where fac.id=facturaId and det.examen_id is not null);	
totalSuministros =     (select count(*) from facturacion_facturacion fac inner join facturacion_facturaciondetalle det ON (det.facturacion_id = fac.id And det.anulado in ('N','R')  and det."estadoRegistro" = 'A')	inner join facturacion_suministros sum ON  (sum.id =det.cums_id) where fac.id=facturaId and det.cums_id is not null );
raise notice 'Total Procedimientos: %s' , totalProcedimientos;
raise notice 'Total Suministros: %s' , totalSuministros;

valorFinalJson := valorFinalJson || ' ' || '{"items":[';

if (totalProcedimientos> 0) then
	for i in 1..totalProcedimientos 
	loop
 	  	SELECT '{"codigoProducto":' || '"' || exa."codigoCups" || '","nombreProducto": ' || '"'|| exa.nombre || '", "cantidad": '|| det.cantidad ||',"unidadMedida": "94", "valorUnitario":' || '"' || det."valorUnitario" || '",' || '"valorTotal":' || '"' || det."valorTotal" || '","impuestos": {"tipo": "01","porcentaje": 0.0,"valor": 0.00}},'
		INTO valorDetalle
		from facturacion_facturacion fac
		inner join facturacion_facturaciondetalle det ON (det.facturacion_id = fac.id And det.anulado in ('N','R') and det."estadoRegistro" = 'A')		
		inner join clinico_examenes exa ON  (exa.id =det.examen_id)
		where fac.id=facturaId and det.examen_id is not null	and det."consecutivoFactura" = i;

		valorFinalJson := valorFinalJson || ' ' || valorDetalle;

	end loop;
end if;
raise notice 'Va esto Procedimientos en el valorFinalJson: %s' , valorFinalJson;

vamos := totalProcedimientos + 1;
hasta := 	totalProcedimientos + totalSuministros;

	mide := length(valorFinalJson);
	RAISE NOTICE 'mide = %s' , mide ;
	SELECT SUBSTRING(valorFinalJson,1, mide-1) INTO valorFinalJson;
	raise notice 'Primero: %s' , valorFinalJson;

	
	valorFinalJson = valorFinalJson||',' ;
	raise notice 'Segundo: %s' , valorFinalJson;


raise notice 'Va esto Procedimientos DESPUES DE QUITAR LA COMA en el valorFinalJson: %s' , valorFinalJson;


if (totalSuministros> 0) then
	
   for i in vamos..hasta 
	loop
	SELECT ' {"codigoProducto":' || '"' || sum.cums || '","nombreProducto": ' || '"'|| sum.nombre || '", "cantidad": '|| det.cantidad ||',"unidadMedida": "94", "valorUnitario":' || '"' || det."valorUnitario" || '",' || '"valorTotal":' || '"' || det."valorTotal" || '","impuestos": {"tipo": "01", "porcentaje": 0.0,"valor": 0.00}},'
	INTO valorDetalleSuministros
	from facturacion_facturacion fac
	inner join facturacion_facturaciondetalle det ON (det.facturacion_id = fac.id And det.anulado in ('N','R')  and det."estadoRegistro" = 'A')		
	inner join facturacion_suministros sum ON  (sum.id =det.cums_id)
	where fac.id=facturaId and det.cums_id is not null and det."consecutivoFactura" = i;

	--valorFinalJson := valorFinalJson || ']';


	valorFinalJson := valorFinalJson || ' ' || valorDetalleSuministros;
	
	end loop;
end if;

	mide := length(valorFinalJson);
	RAISE NOTICE 'mide = %s' , mide ;
	SELECT SUBSTRING(valorFinalJson,1, mide-1) INTO valorFinalJson;
	raise notice 'Primero: %s' , valorFinalJson;

	
	valorFinalJson = valorFinalJson||']},' ;
	raise notice 'Segundo: %s' , valorFinalJson;


--SELECT '{"items": [{"codigoProducto":' || '"' || exa."codigoCups" || '","nombreProducto": ' || '"'|| exa.nombre || '", "cantidad": '|| det.cantidad ||',"unidadMedida": "94", "valorUnitario":' || '"' || det."valorUnitario" || '",' || '"valorTotal":' || '"' || det."valorTotal" || '"}]},{"impuestos": [{"tipo": "01","porcentaje": 19.0,"valor": 19000.00}]},'
--INTO valorDetalle
--from facturacion_facturacion fac
--inner join facturacion_facturaciondetalle det ON (det.facturacion_id = fac.id And det.anulado in ('N','R') and det."estadoRegistro" = 'A')		
--inner join clinico_examenes exa ON  (exa.id =det.examen_id)
--where fac.id=facturaId and det.examen_id is not null		
--UNION
--SELECT '{"items": [{"codigoProducto":' || '"' || sum.cums || '","nombreProducto": ' || '"'|| sum.nombre || '", "cantidad": '|| det.cantidad ||',"unidadMedida": "94", "valorUnitario":' || '"' || det."valorUnitario" || '",' || '"valorTotal":' || '"' || det."valorTotal" || '"}]},{"impuestos": [{"tipo": "01", "porcentaje": 19.0,"valor": 19000.00}]},'
--from facturacion_facturacion fac
--inner join facturacion_facturaciondetalle det ON (det.facturacion_id = fac.id And det.anulado in ('N','R')  and det."estadoRegistro" = 'A')		
--inner join facturacion_suministros sum ON  (sum.id =det.cums_id)
--where fac.id=facturaId and det.cums_id is not null;
--	valorFinalJson := valorFinalJson || ' ' || valorDetalle;

raise notice 'Va esto en Suministros  en el valorFinalJson: %s' , valorDetalleSuministros;

raise notice 'Va esto en Suministros  en el valorFinalJson: %s' , valorFinalJson;


-- Totales de la factura

SELECT '{"totales": {"valorBruto": ' || '"' || 	fac."totalFactura" || '","valorNeto": ' ||  fac."valorApagar"   ||   ',"valorTotalImpuestos": 0.00,"valorTotal":' || fac."valorApagar" || '}}]'
INTO valorTotales
from facturacion_facturacion fac
where fac.id=facturaId ;

	valorFinalJson = valorFinalJson || ' ' || valorTotales;
raise notice 'Va esto totales en el valorFinalJson: %s' , valorFinalJson;


-- FormaPgo

	
end if;

raise notice 'Va esto en el valorFinalJson ANTES DE REPLACE: %s' , valorFinalJson;

--SELECT REPLACE (valorFinalJson, '""', '')
--into valorFinalJson;

--SELECT REPLACE (valorFinalJson, '"null"', 'null')
--into valorFinalJson;

raise notice 'Va esto en el valorFinalJson ESPUES DE REPLACE : %s' , valorFinalJson;
	
--RETURN 'OK'; 
--valorFinalJson = valorFinalJson ||'}}]}]';
 
RETURN valorFinalJson;
END 
$$;


ALTER FUNCTION public.facturajsondian_2(facturaid numeric) OWNER TO postgres;

--
-- Name: generaenvioripsjson1(numeric, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generaenvioripsjson1(envioripsid numeric, tipo character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
 
DECLARE
	 
		valorJson character(500000);
		mide integer := 0;
		facturas RECORD; 
		facturaId integer := 0;
		notaFacturaId integer := 0;
	    valorTransaccionYusuarios character(50000) :='';
	    valorProcedimientos character(50000) :='';
		valorHospitalizacion character(50000) :='';
		valorUrgencias character(50000) :='';
	    valorOtrosServicios character(50000) :='';
	    valorMedicamentos character(50000) :='';
		valorConsultas character(50000) :='';
		totalUrgencias integer := 0;
		totalHospitalizacion integer := 0;
		totalProcedimientos integer := 0;
		totalMedicamentos integer := 0; 
		totalOtrosServicios integer := 0; 
		totalConsultas integer := 0; 
	
		totalRecienNacidos integer := 0;
		valorRecienNacidos character(50000):='';
		contador integer := 1;
		tabla RECORD;
		consecutivos integer[] ;

BEGIN

	valorJson= '[{';
 	FOR facturas IN SELECT "numeroFactura_id", glosa_id, "notaCredito_id" FROM rips_ripsdetalle WHERE "ripsEnvios_id" = envioRipsId
        LOOP

	if (tipo = 'FACTURA') then 
		facturaId:=facturas."numeroFactura_id";
	end if;
	if (tipo = 'GLOSA') then 
		facturaId:=facturas.glosa_id;
		notaFacturaId = facturas.glosa_id;
	end if;

	if (tipo = 'NOTA CREDITO') then 
		facturaId:=facturas."notaCredito_id";
		notaFacturaId := facturas."numeroFactura_id";
	end if;

if (tipo = 'FACTURA') then 
	
	
SELECT '"numDocumentoIdObligado": "' || "numDocumentoIdObligado" ||'",' || '"numFactura": ""' || "numFactura" || '"", "TipoNota": null,"numNota": null,"usuarios": [{'
		||'"tipoDocumentoIdentificacion": '|| '"' ||tiposDoc.codigo || '",'||'"numDocumentoIdentificacion": '|| '"' || u."numDocumentoIdentificacion" || '",'
		||'"tipoUsuario": '|| '"' || CASE WHEN trim(u."tipoUsuario") is null THEN 'null' ELSE u."tipoUsuario"  END    || '",'||'"fechaNacimiento": '|| '"' || u."fechaNacimiento" || '",'
		||'"codSexo": '|| '"' || u."codSexo" || '",'||'"codPaisResidencia": '|| '"' || pais.codigo || '",'||'"codMunicipioResidencia": '|| '"' ||
	CASE WHEN trim(ripsMuni.codigo) is null THEN 'null' ELSE ripsMuni.codigo  END
	|| '",'
		||'"codZonaTerritorialResidencia": '|| '"' ||CASE WHEN trim(zona.codigo) is null THEN 'null' ELSE zona.codigo  END || '",'||'"incapacidad": '|| '"' || u."incapacidad" || '",'
		||'"consecutivo": '|| u."consecutivo" || ',' ||'"codPaisOrigen": '|| '"' ||  pais.codigo
	|| '"' DATO1
INTO valorTransaccionYusuarios
	from rips_ripstransaccion ripstra
	inner join  rips_ripsusuarios u on (u."ripsTransaccion_id" = ripstra.id)
	left join  rips_ripspaises pais on (pais.id =  u."codPaisResidencia_id")
	left join  sitios_municipios muni on ( muni.id = u."codMunicipioResidencia_id")	
	left join  rips_ripsmunicipios ripsMuni on ( ripsMuni.id = muni."ripsMunicipios_id")
	-- inner join usuarios_tiposDocumento tipoDocUsu on (tipoDocUsu.id = cast(u."tipoDocumentoIdentificacion" as integer))
	 inner join rips_ripstiposdocumento tiposDoc on (tiposDoc.id = cast(u."tipoDocumentoIdentificacion" as integer))
	left join rips_ripszonaterritorial zona on (zona.id = cast(u."codZonaTerritorialResidencia_id" as integer))
where  ripstra."ripsEnvio_id" = envioRipsId and ripstra."numFactura" = cast(facturaId as text)  and u."ripsTransaccion_id" = ripstra.id  ;

valorJson = valorJson ||' ' || valorTransaccionYusuarios;

end if;

if (tipo = 'GLOSA') then 
	
SELECT '"numDocumentoIdObligado": "' || "numDocumentoIdObligado" ||'",' || '"numFactura": "' || 'null' || '", "TipoNota":'|| '"' ||tipnot.codigo||'","numNota": ' || ripstra."numNota" || ',"usuarios": [{'
		||'"tipoDocumentoIdentificacion": '|| '"' ||tiposDoc.codigo || '",'||'"numDocumentoIdentificacion": '|| '"' || u."numDocumentoIdentificacion" || '",'
		||'"tipoUsuario": '|| '"' || CASE WHEN trim(u."tipoUsuario") is null THEN 'null' ELSE u."tipoUsuario"  END    || '",'||'"fechaNacimiento": '|| '"' || u."fechaNacimiento" || '",'
		||'"codSexo": '|| '"' || u."codSexo" || '",'||'"codPaisResidencia": '|| '"' || pais.codigo || '",'||'"codMunicipioResidencia": '|| '"' ||
	CASE WHEN trim(ripsMuni.codigo) is null THEN 'null' ELSE ripsMuni.codigo  END
	|| '",'	
		||'"codZonaTerritorialResidencia": '|| '"' ||CASE WHEN trim(zona.codigo) is null THEN 'null' ELSE zona.codigo  END || '",'||'"incapacidad": '|| '"' || u."incapacidad" || '",'
		||'"consecutivo": '|| u."consecutivo" || ',' ||'"codPaisOrigen": '|| '"' ||  pais.codigo
	|| '"' DATO1
INTO valorTransaccionYusuarios
	from rips_ripstransaccion ripstra
	inner join  rips_ripsusuarios u on (u."ripsTransaccion_id" = ripstra.id)
	left join  rips_ripspaises pais on (pais.id =  u."codPaisResidencia_id")
	left join  sitios_municipios muni on ( muni.id = u."codMunicipioResidencia_id")	
	left join  rips_ripsmunicipios ripsMuni on ( ripsMuni.id = muni."ripsMunicipios_id")
--	inner join usuarios_tiposDocumento tipoDocUsu on (tipoDocUsu.id = cast(u."tipoDocumentoIdentificacion" as integer))
	 inner join rips_ripstiposdocumento tiposDoc on (tiposDoc.id = cast(u."tipoDocumentoIdentificacion" as integer))
	left join rips_ripszonaterritorial zona on (zona.id = cast(u."codZonaTerritorialResidencia_id" as integer))
	inner join rips_ripstiposnotas tipnot on (tipnot.id = ripstra."tipoNota_id")	
--where  ripstra."ripsEnvio_id" = envioRipsId and ripstra."numNota" = cast(facturaId as text)  and u."ripsTransaccion_id" = ripstra.id  and ripstra.id=transaccionid;
where  ripstra."ripsEnvio_id" = envioRipsId and ripstra."numNota" = cast(facturaId as text)  and u."ripsTransaccion_id" = ripstra.id  ;

valorJson = valorJson ||' ' || valorTransaccionYusuarios;

end if;

if (tipo = 'NOTA CREDITO') then 
	
SELECT '"numDocumentoIdObligado": "' || "numDocumentoIdObligado" ||'",' || '"numFactura": "' || 'null' || '", "TipoNota":'|| '"' ||tipnot.codigo||'","numNota": ' || ripstra."numNota" || ',"usuarios": [{'
		||'"tipoDocumentoIdentificacion": '|| '"' ||tiposDoc.codigo || '",'||'"numDocumentoIdentificacion": '|| '"' || u."numDocumentoIdentificacion" || '",'
		||'"tipoUsuario": '|| '"' || CASE WHEN trim(u."tipoUsuario") is null THEN 'null' ELSE u."tipoUsuario"  END    || '",'||'"fechaNacimiento": '|| '"' || u."fechaNacimiento" || '",'
		||'"codSexo": '|| '"' || u."codSexo" || '",'||'"codPaisResidencia": '|| '"' || pais.codigo || '",'||'"codMunicipioResidencia": '|| '"' ||
	CASE WHEN trim(ripsMuni.codigo) is null THEN 'null' ELSE ripsMuni.codigo  END
	|| '",'	
		||'"codZonaTerritorialResidencia": '|| '"' ||CASE WHEN trim(zona.codigo) is null THEN 'null' ELSE zona.codigo  END || '",'||'"incapacidad": '|| '"' || u."incapacidad" || '",'
		||'"consecutivo": '|| u."consecutivo" || ',' ||'"codPaisOrigen": '|| '"' ||  pais.codigo
	|| '"' DATO1
INTO valorTransaccionYusuarios
	from rips_ripstransaccion ripstra
	inner join  rips_ripsusuarios u on (u."ripsTransaccion_id" = ripstra.id)
	left join  rips_ripspaises pais on (pais.id =  u."codPaisResidencia_id")
	left join  sitios_municipios muni on ( muni.id = u."codMunicipioResidencia_id")	
	left join  rips_ripsmunicipios ripsMuni on ( ripsMuni.id = muni."ripsMunicipios_id")
--	inner join usuarios_tiposDocumento tipoDocUsu on (tipoDocUsu.id = cast(u."tipoDocumentoIdentificacion" as integer))
	 inner join rips_ripstiposdocumento tiposDoc on (tiposDoc.id = cast(u."tipoDocumentoIdentificacion" as integer))
	left join rips_ripszonaterritorial zona on (zona.id = cast(u."codZonaTerritorialResidencia_id" as integer))
	inner join rips_ripstiposnotas tipnot on (tipnot.id = ripstra."tipoNota_id")	
where  ripstra."ripsEnvio_id" = envioRipsId and ripstra."numNota" = cast(facturaId as text)  and u."ripsTransaccion_id" = ripstra.id; --  and ripstra.id=transaccionid;

valorJson = valorJson ||' ' || valorTransaccionYusuarios;

end if;

raise notice 'Va esto en el JSON INICIAL: %s' , valorJson;

-- Procedimientos

if (tipo = 'FACTURA') then 
	
	totalProcedimientos  = (select count(*) from rips_ripstransaccion ripstra, rips_ripsprocedimientos proc where ripstra."ripsEnvio_id" = envioRipsId and ripstra."numFactura" =cast(facturaId as text ) and proc."ripsTransaccion_id" = ripstra.id and cast("numNota" as float)  = 0   and ripstra."numFactura" = cast(facturaId as text) );

	contador = 1;
	   	FOR tabla IN select * from rips_ripstransaccion ripstra, rips_ripsprocedimientos proc where ripstra."ripsEnvio_id" = envioRipsId and ripstra."numFactura" =cast(facturaId as text ) and proc."ripsTransaccion_id" = ripstra.id 
		LOOP 
          consecutivos[contador] := tabla.consecutivo;
          contador := contador + 1;
		--raise notice 'consecutivos : %' , consecutivos[contador];
		--raise notice 'contador : %' , contador;
		END LOOP;
end if;

if (tipo = 'GLOSA') then 
	totalProcedimientos  = (select count(*) from rips_ripstransaccion ripstra, rips_ripsprocedimientos proc where ripstra."ripsEnvio_id" = envioRipsId and ripstra."numNota" =cast(facturaId as text ) and proc."ripsTransaccion_id" = ripstra.id);	
	contador = 1;
	   	FOR tabla IN select * from rips_ripstransaccion ripstra, rips_ripsprocedimientos proc where ripstra."ripsEnvio_id" = envioRipsId and ripstra."numNota" =cast(facturaId as text ) and proc."ripsTransaccion_id" = ripstra.id
		LOOP 
          consecutivos[contador] := tabla.consecutivo;
          contador := contador + 1;
		raise notice 'consecutivos : %' , consecutivos[contador];
		END LOOP;

end if;

if (tipo = 'NOTA CREDITO') then 
	totalProcedimientos  = (select count(*) from rips_ripstransaccion ripstra, rips_ripsprocedimientos proc where ripstra."ripsEnvio_id" = envioRipsId and ripstra."numNota" =cast(facturaId as text ) and proc."ripsTransaccion_id" = ripstra.id  and cast(ripstra."numFactura" as integer)  = notaFacturaId   );	
	
	
	contador = 1;
	   	FOR tabla IN select * from rips_ripstransaccion ripstra, rips_ripsprocedimientos proc where ripstra."ripsEnvio_id" = envioRipsId and ripstra."numNota" =cast(facturaId as text ) and proc."ripsTransaccion_id" = ripstra.id
		LOOP 
          consecutivos[contador] := tabla.consecutivo;
          contador := contador + 1;
		--raise notice 'consecutivos : %' , consecutivos[contador];
		END LOOP;

end if;

raise notice 'Va esto en el JSON  totalProcedimientos: %s' , totalProcedimientos;

valorJson = valorJson ||',"servicios": { "procedimientos" : [' ;
raise notice 'Detalle JSON PROCED SERVICIOS: %s' , valorJson;

if (totalProcedimientos> 0) then

   contador :=1 ;

   for i in 1..totalProcedimientos 
	loop

	   if (tipo = 'FACTURA') then 
	SELECT '{"codPrestador": '|| '"' || proc."codPrestador" || '",'  ||'"fechaInicioAtencion": '|| '"' || substring(cast(proc."fechaInicioAtencion" as text), 1,16) || '",'  

	 	  '"idMIPRES": ' || '"'   ||CASE WHEN trim(proc."idMIPRES") is null THEN 'null'  WHEN trim(proc."idMIPRES") = null THEN 'null' WHEN trim(proc."idMIPRES") = '' THEN 'null'  ELSE proc."idMIPRES"  END|| '"'  
	   ||',"numAutorizacion": '|| '"' || CASE WHEN trim(proc."numAutorizacion") is null THEN 'null' ELSE proc."numAutorizacion"  END || '"'	
	||',"codProcedimiento": '|| '"' || exa."codigoCups" || '",'	
		||'"viaIngresoServicioSalud": '|| '"' ||proc."viaIngresoServicioSalud_id"  || '",'	
	--	||'"modalidadGrupoServicioTecSal": '|| '"' || proc."modalidadGrupoServicioTecSal_id"  || '",'	
		||'"grupoServicios": '|| '"' ||ripsGrupoServ.codigo || '",'	
	   	||'"codServicio": '||ripsServicios.codigo || ','	
		||'"finalidadTecnologiaSalud": '|| '"' ||CASE WHEN trim(cast(ripsFinalidadConsulta.codigo as text)) is null THEN 'null' ELSE ripsFinalidadConsulta.codigo  END  || '",'			   
	||'"tipoDocumentoIdentificacion": '|| '"' || ripsTiposDoc.codigo  || '"'	
	||',"numDocumentoIdentificacion":  '|| '"' || CASE WHEN trim(proc."numDocumentoIdentificacion") is null THEN 'null' ELSE proc."numDocumentoIdentificacion"  END  || '",'	
	||'"codDiagnosticoPrincipal": '|| '"' || CASE WHEN trim(cast(diag1.cie10 as text)) is null THEN 'null' ELSE diag1.cie10  END || '",'	
	||'"codDiagnosticoRelacionado": '|| '"' ||  CASE WHEN trim(cast(diag2.cie10 as text)) is null THEN 'null' ELSE diag2.cie10  END    || '",'	
	||'"codComplicacion": '|| '"' ||CASE WHEN trim(cast(diag3.cie10 as text)) is null THEN 'null' ELSE diag3.cie10 END   || '",'
	||'"vrServicio": '||proc."vrServicio"   || ','		
	 ||'"conceptoRecaudo": '|| '"' || ripsRecaudo.codigo   || '",'		
	||'"valorPagoModerador": '||  CASE WHEN trim(cast(proc."valorPagoModerador" as text)) is null THEN 0 ELSE proc."valorPagoModerador"  END  || ','	
	||'"numFEVPagoModerador": '|| '"' || proc."numFEVPagoModerador" || '",'
	||'"consecutivo": '||  proc."consecutivo" ||'	},'
	INTO valorProcedimientos
	from rips_ripstransaccion ripstra
	inner join rips_ripsprocedimientos proc on (proc."ripsTransaccion_id" = ripstra.id)
	inner join clinico_examenes exa on (exa.id = proc."codProcedimiento_id" )   
	left join clinico_diagnosticos diag1 on (diag1.id=proc."codDiagnosticoPrincipal_id")   
	left join clinico_diagnosticos diag2 on (diag2.id=proc."codDiagnosticoRelacionado_id")   
	left join clinico_diagnosticos diag3 on (diag3.id=proc."codComplicacion_id")  
	left  join rips_ripsviasingresosalud ripsIngresoSalud ON (ripsIngresoSalud.id = proc."viaIngresoServicioSalud_id")   
	left  join rips_ripsgruposervicios ripsGrupoServ ON (ripsGrupoServ.id = proc."grupoServicios_id")
--	left  join rips_ripsmodalidadgruposerviciosTecSalud  ripsModalidadGrupoServ ON (ripsModalidadGrupoServ.id = proc."modalidadGrupoServicioTecSal_id")
	left  join rips_ripsservicios ripsServicios ON (ripsServicios.id = proc."codServicio_id")
	left  join rips_ripsfinalidadconsulta ripsFinalidadConsulta ON (ripsFinalidadConsulta.id = proc."finalidadTecnologiaSalud_id")	   
	inner join rips_ripstiposdocumento ripsTiposDoc on (ripsTiposDoc.id = proc."tipoDocumentoIdentificacion_id" )
	left join rips_RipsConceptoRecaudo ripsRecaudo on (ripsRecaudo.id = proc."conceptoRecaudo_id")
    where  ripstra."ripsEnvio_id" = envioRipsId AND  ripstra."numFactura" = cast(facturaId as text) and proc.consecutivo = i; 

    raise notice 'valorProcedimientos: %s' , valorProcedimientos;
	valorJson = valorJson ||' '||valorProcedimientos;
	raise notice 'contador: %s' , contador;
    raise notice 'Detalle JSON PROCED ACUMULADO: %s' , valorJson;
	contador := contador +1;

	end if;

	if (tipo = 'GLOSA') then
	SELECT '{"codPrestador": '|| '"' || proc."codPrestador" || '",'  ||'"fechaInicioAtencion": '|| '"' || substring(cast(proc."fechaInicioAtencion" as text), 1,16) || '",'  
	 	  '"idMIPRES": ' || '"'   ||CASE WHEN trim(proc."idMIPRES") is null THEN 'null'  WHEN trim(proc."idMIPRES") = null THEN 'null' WHEN trim(proc."idMIPRES") = '' THEN 'null'  ELSE proc."idMIPRES"  END|| '"'  
	   ||',"numAutorizacion": '|| '"' || CASE WHEN trim(proc."numAutorizacion") is null THEN 'null' ELSE proc."numAutorizacion"  END || '"'	
	||',"codProcedimiento": '|| '"' || exa."codigoCups" || '",'	
		||'"viaIngresoServicioSalud": '|| '"' ||proc."viaIngresoServicioSalud_id"  || '",'	
	--	||'"modalidadGrupoServicioTecSal": '|| '"' || proc."modalidadGrupoServicioTecSal_id"  || '",'	
		||'"grupoServicios": '|| '"' ||ripsGrupoServ.codigo || '",'	
	   	||'"codServicio": '||ripsServicios.codigo || ','	
		||'"finalidadTecnologiaSalud": '|| '"' ||CASE WHEN trim(cast(ripsFinalidadConsulta.codigo as text)) is null THEN 'null' ELSE ripsFinalidadConsulta.codigo  END  || '",'			   
	||'"tipoDocumentoIdentificacion": '|| '"' || ripsTiposDoc.codigo  || '"'	
	||',"numDocumentoIdentificacion":  '|| '"' || CASE WHEN trim(proc."numDocumentoIdentificacion") is null THEN 'null' ELSE proc."numDocumentoIdentificacion"  END  || '",'	
	||'"codDiagnosticoPrincipal": '|| '"' || CASE WHEN trim(cast(diag1.cie10 as text)) is null THEN 'null' ELSE diag1.cie10  END || '",'	
	||'"codDiagnosticoRelacionado": '|| '"' ||  CASE WHEN trim(cast(diag2.cie10 as text)) is null THEN 'null' ELSE diag2.cie10  END    || '",'	
	||'"codComplicacion": '|| '"' ||CASE WHEN trim(cast(diag3.cie10 as text)) is null THEN 'null' ELSE diag3.cie10 END   || '",'
	||'"vrServicio": '|| CASE WHEN proc."notasCreditoGlosa" is null then 0  ELSE proc."notasCreditoGlosa" end   || ','		
	 ||'"conceptoRecaudo": '|| '"' || ripsRecaudo.codigo   || '",'		
	||'"valorPagoModerador": '||  CASE WHEN trim(cast(proc."valorPagoModerador" as text)) is null THEN 0 ELSE proc."valorPagoModerador"  END  || ','	
	||'"numFEVPagoModerador": '|| '"' || proc."numFEVPagoModerador" || '",'
	||'"consecutivo": '||  proc."consecutivo" ||'	},'
	INTO valorProcedimientos
	from rips_ripstransaccion ripstra
	inner join rips_ripsprocedimientos proc on (proc."ripsTransaccion_id" = ripstra.id)
