	inner join rips_ripstiposdocumento ripsTiposDoc on (ripsTiposDoc.id = proc."tipoDocumentoIdentificacion_id" )
	left join rips_RipsConceptoRecaudo ripsRecaudo on (ripsRecaudo.id = proc."conceptoRecaudo_id")	   
